{"files":[{"path":"daily_net.py","content":"import csv
import sys
import os
import re
from decimal import Decimal, InvalidOperation
from collections import defaultdict

REQUIRED = ["paid_at", "channel", "status", "amount", "refund_amount"]
ALLOWED_STATUS = {"PAID", "REFUNDED", "CANCELLED"}
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def fail(row_no, field, msg):
    if row_no is None:
        sys.stderr.write("error: %s: %s\n" % (field, msg))
    else:
        sys.stderr.write("error: row %d field %s: %s\n" % (row_no, field, msg))
    sys.exit(2)


def valid_date(s):
    if not DATE_RE.match(s):
        return False
    try:
        y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    except ValueError:
        return False
    if m < 1 or m > 12:
        return False
    if d < 1:
        return False
    leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    days = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return d <= days[m - 1]


def parse_amount(s, row_no, field):
    if s is None:
        fail(row_no, field, "missing value")
    t = s.strip()
    if t == "":
        fail(row_no, field, "empty value")
    low = t.lower()
    if low in ("nan", "inf", "+inf", "-inf", "infinity", "+infinity", "-infinity"):
        fail(row_no, field, "not a finite number")
    if t.startswith("+"):
        t = t[1:]
    if t.startswith("-"):
        fail(row_no, field, "negative amount")
    if not re.match(r"^\d+(\.\d+)?$", t):
        fail(row_no, field, "invalid decimal")
    if "." in t:
        frac = t.split(".", 1)[1]
        if len(frac) > 2:
            fail(row_no, field, "more than two decimal places")
    try:
        v = Decimal(t)
    except InvalidOperation:
        fail(row_no, field, "invalid decimal")
    if not v.is_finite():
        fail(row_no, field, "not a finite number")
    if v < 0:
        fail(row_no, field, "negative amount")
    return v


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("usage: python daily_net.py input.csv output.csv\n")
        sys.exit(2)
    in_path, out_path = sys.argv[1], sys.argv[2]
    try:
        if os.path.realpath(in_path) == os.path.realpath(out_path):
            sys.stderr.write("error: input and output paths are the same\n")
            sys.exit(2)
    except OSError:
        pass

    try:
        with open(in_path, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f)
            try:
                header = next(reader)
            except StopIteration:
                fail(None, "header", "missing header")
            header = [h.strip() for h in header]
            idx = {}
            for name in REQUIRED:
                if name not in header:
                    fail(None, name, "missing required column")
                idx[name] = header.index(name)

            totals = defaultdict(Decimal)
            row_no = 0
            for row in reader:
                row_no += 1
                if len(row) == 0:
                    continue
                if all(c.strip() == "" for c in row):
                    continue

                def get(name):
                    i = idx[name]
                    if i >= len(row):
                        fail(row_no, name, "missing value")
                    return row[i]

                status = get("status").strip()
                if status not in ALLOWED_STATUS:
                    fail(row_no, "status", "unknown status %r" % status)
                if status == "CANCELLED":
                    continue

                paid_at = get("paid_at").strip()
                if not valid_date(paid_at):
                    fail(row_no, "paid_at", "invalid date")

                channel = get("channel").strip()
                if channel == "":
                    fail(row_no, "channel", "empty channel")

                amount = parse_amount(get("amount"), row_no, "amount")
                refund = parse_amount(get("refund_amount"), row_no, "refund_amount")
                if refund > amount:
                    fail(row_no, "refund_amount", "greater than amount")

                totals[(paid_at, channel)] += amount - refund
    except UnicodeDecodeError:
        fail(None, "file", "not valid UTF-8")
    except csv.Error as e:
        fail(None, "file", "CSV error: %s" % e)
    except OSError as e:
        sys.stderr.write("error: cannot read input: %s\n" % e)
        sys.exit(2)

    lines = []
    for (date, channel) in sorted(totals.keys()):
        val = totals[(date, channel)]
        lines.append([date, channel, format(val, ".2f")])

    try:
        with open(out_path, "w", encoding="utf-8", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["date", "channel", "net_amount"])
            writer.writerows(lines)
    except OSError as e:
        sys.stderr.write("error: cannot write output: %s\n" % e)
        sys.exit(2)


if __name__ == "__main__":
    main()
